<?php
declare(strict_types=1);
function oauth_config(array $config, string $provider): array { $p=$config['oauth'][$provider]??[]; if(empty($p['client_id'])||empty($p['client_secret'])||empty($p['redirect_uri'])) throw new RuntimeException(ucfirst($provider).' OAuth is not configured.'); return $p; }
function oauth_http(string $url, array $options=[]): array { $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>$options['headers']??[]]); if(isset($options['post'])){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,http_build_query($options['post']));} $body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($body===false||$status<200||$status>=300)throw new RuntimeException('OAuth provider request failed'.($err?': '.$err:''));$json=json_decode($body,true);if(!is_array($json))throw new RuntimeException('Invalid OAuth provider response.');return $json; }
function unique_username(PDO $pdo,string $base):string{$base=preg_replace('/[^A-Za-z0-9_]/','_',trim($base))?:'user';$base=substr($base,0,24);$candidate=$base;$i=1;$q=$pdo->prepare('SELECT 1 FROM users WHERE username=?');while(true){$q->execute([$candidate]);if(!$q->fetchColumn())return $candidate;$candidate=substr($base,0,24).$i++;}}
function oauth_finish_login(PDO $pdo,string $provider,string $providerId,?string $email,string $displayName,string $username,bool $emailVerified=false):int{$q=$pdo->prepare('SELECT user_id FROM user_identities WHERE provider=? AND provider_user_id=?');$q->execute([$provider,$providerId]);if($id=$q->fetchColumn())return(int)$id;if(!empty($_SESSION['user_id'])){$userId=(int)$_SESSION['user_id'];$q=$pdo->prepare('INSERT INTO user_identities(user_id,provider,provider_user_id,provider_email) VALUES(?,?,?,?)');$q->execute([$userId,$provider,$providerId,$email]);return$userId;}if($email&&$emailVerified){$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([strtolower($email)]);if($existing=$q->fetchColumn()){$userId=(int)$existing;$q=$pdo->prepare('INSERT INTO user_identities(user_id,provider,provider_user_id,provider_email) VALUES(?,?,?,?)');$q->execute([$userId,$provider,$providerId,$email]);return$userId;}}$username=unique_username($pdo,$username?:strtolower(str_replace(' ','_',$displayName)));$q=$pdo->prepare('INSERT INTO users(public_id,username,display_name,email,password_hash) VALUES(?,?,?,?,NULL)');$q->execute([ulid_like(),$username,$displayName?:$username,$email?strtolower($email):null]);$userId=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO user_identities(user_id,provider,provider_user_id,provider_email) VALUES(?,?,?,?)');$q->execute([$userId,$provider,$providerId,$email]);return$userId;}
